import {renderAtlasDemo} from './atlas-labs.js';
// Meaning-led controls: all visual previews remain provisional until Check.
export function renderRenewal(q,lab,locked,art,esc){
 const s=lab.settings,off=locked?'disabled':'',names={word:'① 找到任务词',job:'② 投递到本句职业',block:'① 选择整组词块',role:'② 接到句中角色',plan:'① 选择骨架房',ending:'② 连接末端关系',work:'① 选择 be 的工作灯',meaning:'② 对应整组意义',track:'① 按语境选择轨道',form:'② 接好后面的内容',mode:'① 给 it 选择舞台',anchor:'② 连接对象、内容或焦点'};
 const button=(axis,v,t)=>`<button data-action="lab-direct" data-axis="${axis}" data-value="${esc(v)}" aria-pressed="${s[axis]===v}" class="${s[axis]===v?'selected':''}" ${off}>${esc(t)}</button>`;
 const text=(axis)=>esc(q.axes[axis]?.find(([v])=>v===s[axis])?.[1]||'等待你的选择');
 let stage='';
 if(q.type==='postbox')stage=`<div class="post-office"><div class="post-letter ${s.job?'posted':''}"><span>本次任务词</span><strong lang="en">${esc(s.word||'选一张词卡')}</strong><i>✉</i></div><div class="mail-row">${q.axes.job.map(([v,t])=>`<div class="post-slot ${s.job===v?'receiving':''}"><span>${({noun:'◉',verb:'➜',adj:'✿',adv:'≋'})[v]}</span><i></i><strong>${esc(t)}</strong>${s.job===v?'<b>✉</b>':''}</div>`).join('')}</div><p class="renewal-caption">你的投递预览：${text('job')}。先看句中工作，检查后再看解释。</p></div>`;
 if(q.type==='rail')stage=`<div class="role-yard"><div class="rail-track">${q.blocks.map(b=>`<div class="rail-wagon ${s.block===b?'coupled':''}"><strong lang="en">${esc(b)}</strong><i></i><i></i></div>`).join('')}</div><div class="role-signal ${s.block&&s.role?'wired':''}"><span>${s.block?esc(s.block):'待连接词块'}</span><i>⟶</i><strong>${text('role')}</strong></div><p class="renewal-caption">同一词组可以有内部修饰词；先确认任务要整组还是其中一词。</p></div>`;
 if(q.type==='architect'){
 const slots=({SV:['主体','动词'],SVO:['主体','动词','对象'],SVOO:['主体','动词','接受者','递交物'],SVP:['主体','连接动词','主语描述'],SVOC:['主体','动词','对象','对象描述']})[s.plan]||[];
 stage=`<div class="blueprint"><div class="blueprint-roof">${text('plan')}</div><div class="blueprint-slots">${slots.map((slot,i)=>`<div style="--delay:${i*.12}s"><small>${slot}</small><strong lang="en">${esc(q.blocks[i]||'〔缺少对应内容〕')}</strong></div>`).join('')}</div><div class="building-cable"><span>${text('ending')}</span><i></i></div><p class="renewal-caption">图按你选择的骨架试摆，不代表已经正确。检查角色关系，尤其是送给谁和把谁变怎样。</p></div>`;
 }
 if(q.type==='beacon')stage=`<div class="be-workshop"><div class="be-bulbs">${q.axes.work.map(([v,t])=>`<div class="be-bulb ${s.work===v?'lit':''}"><i></i><strong>${esc(t)}</strong></div>`).join('')}</div><div class="be-circuit ${s.work||''}"><span>be</span><i></i><div>${art(q.icon)}</div><strong>${text('meaning')}</strong></div><p class="renewal-caption">点灯只是你的结构判断；进行、被动与连接状态要看完整表达。</p></div>`;
 if(q.type==='album'){
 const t=s.track;stage=`<div class="habit-studio ${t||'waiting'}"><div class="habit-tabs">${q.axes.track.map(([v,t])=>`<span class="${s.track===v?'on':''}">${esc(t)}</span>`).join('')}</div><div class="habit-scene"><div class="habit-picture">${art(q.icon)}</div>${t==='past'?'<div class="old-days"><span>以前 ↻ ↻ ↻</span><i>→</i><span>如今：看题目中的变化</span></div>':t==='familiar'?'<div class="comfort"><b>✓</b><span>熟悉的状态</span></div>':t==='adapting'?'<div class="adapt-steps"><i></i><i></i><i></i><span>逐渐适应 · 非精确进度</span></div>':t==='tool'?'<div class="tool-path"><span>被使用物</span><i>→</i><strong>用途</strong></div>':'<p>先选择一种意义轨道</p>'}</div><div class="habit-form" lang="en">${esc(q.frame.replace('{form}',s.form||'___'))}</div><p class="renewal-caption">试选轨道不自动判对。熟悉不等于过去常做，工具用途也不是适应。</p></div>`;
 }
 if(q.type==='spotlight')stage=`<div class="it-theatre mode-${s.mode||'waiting'}"><div class="theatre-curtain"></div><div class="it-stand">it</div><div class="it-wire ${s.anchor?'connected':''}">${s.mode==='weather'?'不画实物指代线':s.mode==='focus'?'聚光焦点':s.mode==='refer'?'回到上下文对象':s.mode==='object'?'宾语位置 → 后置内容':'主语位置 → 后置内容'}</div><div class="it-backstage ${s.anchor?'occupied':''}"><span>${text('anchor')}</span>${s.mode==='focus'?'<i class="spot-beam"></i>':''}</div><div class="it-art">${art(q.icon)}</div><p class="renewal-caption">舞台按你的选择展示。先保留人物、动作和对象，再检查 it 的本次功能。</p></div>`;
 const keys=Object.keys(q.axes),filled=keys.every(k=>s[k]);
 return `<div class="renewal-lab"><ol class="operation-trail" aria-label="操作进度">${keys.map((k,i)=>`<li class="${s[k]?'done':''}"><b>${s[k]?'✓':i+1}</b>${names[k]?.slice(2)||k}</li>`).join('')}</ol>${stage}<div class="renewal-controls">${keys.map(k=>`<fieldset><legend>${names[k]}</legend>${q.axes[k].map(([v,t])=>button(k,v,t)).join('')}</fieldset>`).join('')}</div><button class="primary" data-action="check-lab" ${locked||!filled?'disabled':''}>检查我的连接 ✓</button><p class="interaction-tip">${filled?'两步都好了，可以检查。':'先做第一步，再补齐另一项；选项可以反复修改。'}</p></div>`;
}
export function renderLessonDemo(l,value,art,esc){
 const d=l.demo;if(!d)return '';if(d.kind==='atlas')return renderAtlasDemo(l,value,art,esc);const at=d.states.find(x=>x.value===value)||d.states[0];
 return `<div id="lesson-demo" class="lesson-demo demo-${d.id} state-${at.value}"><div class="demo-top"><strong>观察小实验 · 不计分</strong><span>切换后可听一句完整英文</span></div><div class="demo-controls">${d.states.map((x,i)=>`<button data-action="lesson-demo" data-value="${x.value}" aria-pressed="${at.value===x.value}" class="${at.value===x.value?'selected':''}">观察 ${i+1}</button>`).join('')}</div><div class="demo-art">${art(at.art)}</div><p lang="en">${esc(at.text)}</p><p>${esc(at.note)}</p><button class="sound-button" data-action="speak" data-text="${esc(at.text)}">♫ 听这句话</button></div>`;
}
